import static org.jsoup.helper.UrlBuilder.build;
import static org.jsoup.helper.UrlBuilder.appendKeyVal;
import static org.junit.Assert.*;
import org.jsoup.helper.UrlBuilder;
import org.jsoup.Connection;
import org.jsoup.Connection.KeyVal;
import org.junit.Test;
import java.net.URL;
import java.net.MalformedURLException;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {
    @Test
    public void buildTest() throws MalformedURLException {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL resultUrl = urlBuilder.build();
        assertEquals(inputUrl, resultUrl);
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValTest() throws UnsupportedEncodingException {
        KeyVal kv = new KeyVal("key", "value");
        UrlBuilder urlBuilder = new UrlBuilder(null);
        urlBuilder.appendKeyVal(kv);
    }
}
```

This code has two test methods, `buildTest` and `appendKeyValTest`. `buildTest` tests the `UrlBuilder.build` method by creating an instance of `UrlBuilder` with a valid `URL` and asserts that the same `URL` is returned by the `build` method. `appendKeyValTest` tests the `UrlBuilder.appendKeyVal` method by creating an instance of `UrlBuilder` with `null` input and asserts that the method throws an `UnsupportedEncodingException`.
